var i=46;var n=[{id:`cooking-046-01`,theoryId:46,type:`single_choice`,difficulty:`beginner`,safetyCritical:!0,question:{en:`Why can food look browned before being safely cooked inside?`,ua:`Чому продукт може мати скоринку, але залишатися небезпечно недоготовленим усередині?`},explanation:{en:`Browning indicates surface reactions, not validated core doneness.`,ua:`Підрум’янення відображає поверхневі реакції, а не перевірену готовність усередині.`},options:[{id:`a`,text:{en:`Surface heats and dries faster than the center`,ua:`Поверхня нагрівається й висихає швидше за середину`}},{id:`b`,text:{en:`Browning measures the center temperature`,ua:`Колір скоринки показує внутрішню температуру`}},{id:`c`,text:{en:`The center always cooks first`,ua:`Середина завжди готується першою`}}],answer:{optionIds:[`a`]}},{id:`cooking-046-02`,theoryId:46,type:`true_false`,difficulty:`beginner`,safetyCritical:!0,question:{en:`A dark crust guarantees a safe center temperature.`,ua:`Темна скоринка гарантує безпечну температуру в центрі.`},explanation:{en:`Use an appropriate food thermometer for foods with safety endpoints.`,ua:`Для продуктів із вимогами безпечності потрібен відповідний харчовий термометр.`},answer:{value:!1}},{id:`cooking-046-03`,theoryId:46,type:`matching`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Match observation to what it tells the cook.`,ua:`Поєднайте ознаку з інформацією для кухаря.`},explanation:{en:`Different observations describe different regions and processes.`,ua:`Різні ознаки стосуються різних частин продукту й процесів.`},leftItems:[{id:`l1`,text:{en:`Brown crust`,ua:`Рум’яна скоринка`}},{id:`l2`,text:{en:`Probe at thickest center`,ua:`Термощуп у найтовщій частині`}},{id:`l3`,text:{en:`Wet steaming surface`,ua:`Волога поверхня з парою`}}],rightItems:[{id:`r3`,text:{en:`Evaporation limiting browning`,ua:`Випаровування обмежує утворення скоринки`}},{id:`r2`,text:{en:`Approximate internal temperature`,ua:`Приблизна внутрішня температура`}},{id:`r1`,text:{en:`Surface has undergone browning reactions`,ua:`На поверхні відбулися реакції підрум’янення`}}],answer:{pairs:[{leftId:`l1`,rightId:`r1`},{leftId:`l2`,rightId:`r2`},{leftId:`l3`,rightId:`r3`}]}},{id:`cooking-046-04`,theoryId:46,type:`sequence`,difficulty:`intermediate`,safetyCritical:!0,question:{en:`Order a safe approach to a thick, browned chicken portion.`,ua:`Упорядкуйте безпечну роботу з товстим шматком курятини з рум’яною скоринкою.`},explanation:{en:`Surface appearance alone cannot confirm core safety.`,ua:`Зовнішній вигляд не може сам по собі підтвердити безпечність середини.`},steps:[{id:`s2`,text:{en:`Measure center temperature with a suitable thermometer`,ua:`Виміряти температуру в центрі належним термометром`}},{id:`s1`,text:{en:`Recognize crust does not prove center is cooked`,ua:`Не вважати скоринку доказом готовності всередині`}},{id:`s3`,text:{en:`Continue cooking until the required safe endpoint is verified`,ua:`Продовжити приготування до підтвердження потрібної безпечної температури`}}],answer:{order:[`s1`,`s2`,`s3`]}},{id:`cooking-046-05`,theoryId:46,type:`find_mistake`,difficulty:`intermediate`,safetyCritical:!0,question:{en:`Which statement is a cooking-safety mistake?`,ua:`Яке твердження є помилкою щодо безпеки приготування?`},explanation:{en:`Visual browning and food-safety endpoints are independent.`,ua:`Колір скоринки та критерій безпечної готовності — різні речі.`},options:[{id:`a`,text:{en:`Use an internal thermometer for chicken`,ua:`Вимірювати внутрішню температуру курятини`}},{id:`b`,text:{en:`A brown chicken skin proves the meat is safe to eat`,ua:`Коричнева шкіра курятини доводить, що її безпечно їсти`}},{id:`c`,text:{en:`Adjust heat to prevent burnt outsides`,ua:`Регулювати нагрівання, щоб не спалити поверхню`}}],answer:{optionIds:[`b`]}},{id:`cooking-046-06`,theoryId:46,type:`multiple_choice`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Which observations can help confirm a poultry portion is safely cooked?`,ua:`Які дії допомагають підтвердити безпечність готової порції птиці?`},explanation:{en:`Safety is established by validated time–temperature measures, not color alone.`,ua:`Безпечність підтверджують перевіреними параметрами часу й температури, а не тільки кольором.`},options:[{id:`a`,text:{en:`Check internal temperature at the appropriate location`,ua:`Перевірити внутрішню температуру у відповідному місці`}},{id:`b`,text:{en:`Apply the relevant validated time–temperature endpoint`,ua:`Застосувати відповідний підтверджений режим часу й температури`}},{id:`c`,text:{en:`Rely only on brown skin color`,ua:`Покладатися лише на коричневий колір шкіри`}},{id:`d`,text:{en:`Use a suitable food thermometer`,ua:`Використовувати відповідний харчовий термометр`}}],answer:{optionIds:[`a`,`b`,`d`]}}];var a={theoryId:46,exercises:n};export{a as default,n as exercises,i as theoryId};